{
  "name": "wlc_phy_band_init",
  "confidence": "medium",
  "docstring": "Initialize a PHY band context by setting a byte field at offset 52 to 1, clearing a byte field at offset 163, and zeroing a dword field at offset 184.",
  "subsystem": "phy",
  "var_renames": {
    "result": "phy_ctx"
  },
  "struct_hints": [
    {
      "offset": 52,
      "meaning": "byte field marked active/enabled"
    },
    {
      "offset": 163,
      "meaning": "radio or band-state byte cleared"
    },
    {
      "offset": 184,
      "meaning": "band/channel-related dword cleared"
    }
  ]
}
